const i = $input.first().json;

const query = String(i.query ?? '').trim();
if (!query) throw new Error('wf-step-retrieve called with an empty query');

// kb.documents.doc_type allows book|style_guide|article|datasheet|note.
// Anything else means the caller guessed, so drop it to '' (= whole corpus).
// `note` stays out on purpose: kb.documents has 0 rows of it (measured 2026-09-14).
const allowed = ['book', 'style_guide', 'article', 'datasheet'];
const dt = String(i.doc_type ?? '').trim().toLowerCase();

const k = Number(i.top_k);

// ⛔ `mode` MUST be carried through — `Return rows` reads it from this node, not
// from the trigger. Dropping it here silently forces the text shape, and every
// capability that asked for `rows` gets an empty array.
const mode = String(i.mode ?? 'text').trim().toLowerCase() === 'rows' ? 'rows' : 'text';

// ⛔ The web arm searches THIS, not `query`. They are different questions when the
// caller rewrote for retrieval: cap-brainstorm-pairing searches the corpus for the
// bare anchor ("Talus"), which is right for a vector search over chunks and wrong
// for a web search -- it returns pages ABOUT Talus when the brewer asked what goes
// WITH it. measured 2026-09-15: with query=anchor the pairing propose step
// correctly returned zero candidates, because nothing it was shown answered the
// question. Falls back to `query` so every existing caller is unaffected.
const web_query = String(i.web_query ?? '').trim() || query;

return [{ json: {
  query,
  web_query,
  mode,
  // Carried for the retrieval trace only; never used in the search itself.
  session_id: String(i.session_id ?? '').trim(),
  doc_type: allowed.includes(dt) ? dt : '',
  top_k: Number.isFinite(k) && k > 0 ? Math.min(Math.round(k), 8) : 6,
}}];

const src  = $('Normalise input').first().json;
const mode = String(src.mode ?? 'text').toLowerCase() === 'rows' ? 'rows' : 'text';

// Always Output Data is ON upstream, so a zero-row search arrives as one empty
// item. Filtering on chunk_id is what turns that back into "no results".
const raw = $('Search knowledge').all().map(i => i.json).filter(r => r.chunk_id != null);

// Words in the question the corpus vocabulary has never seen, after the
// typo/locale and off-domain guards (nlq.corpus_vocabulary_gap). One value per
// call, repeated on every row by the search query.
//
// ⭐ It now HAS a consumer: `Gap?` routes a non-empty gap to the web arm, which
// is why it reaches the `text` shape below. The old note here said the opposite,
// and it was right at the time -- a fact the model cannot act on only makes it
// hedge. It can act on this one now.
const gap = $('Search knowledge').first().json.gap_terms ?? [];

// ⛔ `Web arm` only runs on the true branch, so referencing it on the false
// branch THROWS rather than returning empty. try/catch is load-bearing.
// onError:continueRegularOutput also means a failed call arrives as an item
// carrying `error` and no `rows` -- treat that exactly like no web results.
let web = [];
let webError = null;
try {
  const w = $('Web arm').first().json ?? {};
  web = Array.isArray(w.rows) ? w.rows : [];
  webError = w.error ?? null;
} catch (e) { /* gate was false: no web arm on this path */ }

const rows = raw.map(r => ({
  chunk_id: Number(r.chunk_id),
  doc_title: r.doc_title,
  heading: Array.isArray(r.heading_path)
    ? r.heading_path.join(' > ')
    : String(r.heading_path ?? ''),
  page: r.page_from ?? null,
  text: String(r.raw_content).replace(/\s+/g, ' ').trim(),
}));

// Structured shape — for capabilities. Empty is a valid answer, not an error;
// the caller decides whether zero results is fatal.
if (mode === 'rows') {
  return [{ json: { query: src.query, count: rows.length, gap, web, rows } }];
}

// Text shape — for the model. ONE item, ONE key.
if (!rows.length && !web.length) {
  return [{ json: { response: `No passages in the library matched "${src.query}".` } }];
}

const libraryBlock = rows.length
  ? `${rows.length} passages from the library for "${src.query}":\n\n` +
    rows.map((x, n) =>
      `[S${n + 1}] ${x.doc_title} · ${x.heading}${x.page ? ` · p.${x.page}` : ''}\n${x.text}`
    ).join('\n\n')
  : `No passages in the library matched "${src.query}".`;

if (!web.length) {
  // A gap fired but the web returned nothing usable (every candidate refused the
  // fetch, or the arm errored). Say so plainly rather than silently look covered.
  const why = gap.length
    ? `\n\nThe library does not cover ${gap.map(t => `"${t}"`).join(', ')}, and no usable web source was reachable${webError ? ' (web search failed)' : ''}.`
    : '';
  return [{ json: { response: libraryBlock + why } }];
}

// ⛔ [W..] is deliberately a DIFFERENT marker from [S..], and the framing below
// is an instruction the model reads, not decoration. Web passages are not in the
// library, carry none of its editorial vetting, and must never be presented as
// though they were: an answer that blurs the two is the failure this whole
// citation scheme exists to prevent.
const webBlock = web.map((x, n) =>
  `[W${n + 1}] ${x.url}${x.heading ? ` · ${x.heading}` : ''}\n${x.text}`
).join('\n\n');

const gapNote = gap.length
  ? `Your library has never seen ${gap.map(t => `"${t}"`).join(', ')}, so these came from the web.`
  : 'These came from the web, not your library.';

return [{ json: {
  response: `${libraryBlock}\n\n---\n${gapNote}\n` +
    `Cite them as [W1], [W2] — NOT as [S1] — and tell the reader plainly that ` +
    `this part is from the web and is not in their library.\n\n${webBlock}`,
}}];

const src = $('Normalise input').first().json;
const emb = $json.embeddings?.[0];

if (!Array.isArray(emb) || emb.length !== 1024) {
  throw new Error(`Expected a 1024-dim embedding, got ${emb?.length} — is bge-m3 loaded?`);
}

// pgvector literal, cast with $2::vector downstream. A JS array would arrive as a
// Postgres array, not a vector.
return [{ json: { ...src, embedding: '[' + emb.join(',') + ']' } }];
